{"implementation":"import math

def solve(case):
    if type(case) is not dict:
        raise ValueError('case must be an object')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('missing required case field')
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if type(nodes) is not list or type(required_symbols) is not list:
        raise ValueError('invalid case field type')

    required = set()
    for symbol in required_symbols:
        if type(symbol) is not str:
            raise ValueError('required symbol must be a string')
        if symbol in required:
            raise ValueError('duplicate required symbol')
        required.add(symbol)

    by_id = {}
    for node in nodes:
        if type(node) is not dict:
            raise ValueError('node must be an object')
        for field in ('id', 'parent', 'symbol', 'depth', 'removable', 'utility'):
            if field not in node:
                raise ValueError('missing required node field')
        node_id = node['id']
        parent = node['parent']
        if type(node_id) is not str or not node_id:
            raise ValueError('invalid node id')
        if node_id in by_id:
            raise ValueError('duplicate node id')
        if parent is not None and type(parent) is not str:
            raise ValueError('invalid parent id')
        if type(node['symbol']) is not str:
            raise ValueError('invalid symbol')
        if type(node['depth']) is not int or node['depth'] < 0:
            raise ValueError('invalid depth')
        if type(node['removable']) is not bool:
            raise ValueError('invalid removable flag')
        utility = node['utility']
        if type(utility) not in (int, float) or not math.isfinite(utility):
            raise ValueError('invalid utility')
        by_id[node_id] = node

    roots = [node for node in nodes if node['parent'] is None]
    if len(roots) != 1:
        raise ValueError('tree must have exactly one root')
    root_id = roots[0]['id']
    if roots[0]['depth'] != 0:
        raise ValueError('root depth must be zero')

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            if parent not in by_id or parent == node['id']:
                raise ValueError('invalid parent reference')
            if node['depth'] != by_id[parent]['depth'] + 1:
                raise ValueError('inconsistent depth')
            children[parent].append(node['id'])

    represented = {symbol: 0 for symbol in required}
    for node in nodes:
        symbol = node['symbol']
        if symbol in represented:
            represented[symbol] += 1
    if any(count == 0 for count in represented.values()):
        raise ValueError('required symbol is not represented')

    ordered = sorted(nodes, key=lambda node: (-node['depth'], node['id']))
    retained = set(by_id)
    removed = []
    for node in ordered:
        node_id = node['id']
        symbol = node['symbol']
        if node_id == root_id or not node['removable'] or symbol in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        if symbol in represented and represented[symbol] <= 1:
            continue
        retained.remove(node_id)
        removed.append(node_id)
        if symbol in represented:
            represented[symbol] -= 1

    return {
        'removed_node_ids': removed,
        'retained_node_ids': sorted(retained),
    }
"}
